import React from 'react';
import { AppProvider } from './context/AppContext';
import Dashboard from './pages/Dashboard';

function App() {
  return (
    <AppProvider>
      <Dashboard />
    </AppProvider>
  );
}

export default App;
export const getGraphSummary    = () => api.get('/detections/graphs/summary');
export const getGraphConfidence = () => api.get('/detections/graphs/confidence');
export const getGraphTimeline   = () => api.get('/detections/graphs/timeline');
